  q1: ['c', 'rust', 'go'],
  q2: ['html', 'css', 'javascript'],
  q3: ['java', 'c-sharp', 'ruby'],
};

const QUESTION_LABELS = {
  q1: 'Compiled languages',
  q2: 'Front-end web languages',
  q3: 'OOP-supporting languages',
};

const CORRECT_LABELS = {
  q1: 'C, Rust, and Go are compiled. Python is interpreted.',
  q2: 'HTML, CSS, and JavaScript are the core front-end trio. COBOL is a legacy business language.',
  q3: 'Java, C#, and Ruby all support OOP. Assembly operates at a hardware level with no OOP concepts.',
};

document.getElementById('quiz-form').addEventListener('submit', function (e) {
  e.preventDefault();

  const resultsEl = document.getElementById('results');
  resultsEl.innerHTML = '';
  resultsEl.classList.remove('hidden');

  let totalScore = 0;
  const items = [];

  for (const [key, correct] of Object.entries(ANSWERS)) {
    const selected = Array.from(
      document.querySelectorAll(`input[name="${key}"]:checked`)
    ).map(cb => cb.value);

    const correctSet = new Set(correct);
    const selectedSet = new Set(selected);

    const allCorrectSelected = correct.every(v => selectedSet.has(v));
    const noWrongSelected = selected.every(v => correctSet.has(v));

    let status, icon;
    if (allCorrectSelected && noWrongSelected) {
      status = 'correct';
      icon = '✓';
      totalScore++;
    } else if (selected.length === 0) {
      status = 'wrong';
      icon = '✗';
    } else if (selected.some(v => correctSet.has(v))) {
      status = 'partial';
      icon = '◑';
    } else {
      status = 'wrong';
      icon = '✗';
    }

    items.push({ key, status, icon });
  }

  const heading = document.createElement('h2');
  heading.textContent = 'Your Results';
  resultsEl.appendChild(heading);

  items.forEach(({ key, status, icon }) => {
    const div = document.createElement('div');
    div.className = `result-item ${status}`;

    const statusText = status === 'correct' ? 'Correct!' : status === 'partial' ? 'Partially correct' : 'Incorrect';

    div.innerHTML = `
      <span class="result-icon">${icon}</span>
      <div class="result-text">
        <strong>Q${key.slice(1)} — ${QUESTION_LABELS[key]}: ${statusText}</strong>
        <span>${CORRECT_LABELS[key]}</span>
      </div>
    `;
    resultsEl.appendChild(div);
  });

  const banner = document.createElement('div');
  banner.className = 'score-banner';
  banner.innerHTML = `
    <div class="score-value">${totalScore} / ${Object.keys(ANSWERS).length}</div>
    <div class="score-label">${scoreMessage(totalScore)}</div>
  `;
  resultsEl.appendChild(banner);

  resultsEl.scrollIntoView({ behavior: 'smooth', block: 'start' });
});

function scoreMessage(score) {
  if (score === 3) return '🎉 Perfect score — you really know your languages!';
  if (score === 2) return '👍 Good effort — almost there!';
  if (score === 1) return '📚 Keep studying — you\'ll get it next time.';
  return '💡 No worries — review the answers and try again!';
}
