+
+.result-icon {
+  font-size: 1rem;
+  flex-shrink: 0;
+  margin-top: 1px;
+}
+
+.result-text strong {
+  display: block;
+  margin-bottom: 2px;
+}
+
+.result-text span {
+  opacity: 0.85;
